import {newId} from './cloud.js';
export function createCafeChatUI(shell,cloud,onOrder=()=>{}){
 const root=document.createElement('div');root.className='cafe-chat';root.hidden=true;
 root.innerHTML='<button class="cafe-chat-open" type="button">和主理熊聊聊</button><section hidden aria-label="与主理熊聊天"><div class="cafe-chat-head"><small>泊舟 · AI · 仅自己可见</small><button class="cafe-chat-fold" type="button" aria-label="收起聊天">×</button></div><div class="cafe-chat-log" aria-live="polite"></div><p class="cafe-chat-error" role="status"></p><form><input aria-label="想对主理熊说的话" placeholder="今天想聊些什么？" maxlength="600" autocomplete="off"><button type="submit">发送</button></form></section>';
 shell.append(root);const panel=root.querySelector('section'),log=root.querySelector('.cafe-chat-log'),form=root.querySelector('form'),input=root.querySelector('input'),send=form.querySelector('button'),error=root.querySelector('.cafe-chat-error');let seated=false,busy=false,generation=0,pending=null;
 function line(text,who){const p=document.createElement('p');p.className=who;p.textContent=text;log.append(p);while(log.children.length>24)log.firstChild.remove();log.scrollTop=log.scrollHeight}
 root.querySelector('.cafe-chat-open').onclick=()=>{panel.hidden=false;root.querySelector('.cafe-chat-open').hidden=true;if(!log.children.length)line('我是泊舟，这家店的主理熊。想喝点什么，或者只是来坐坐？','host')};
 function fold(){panel.hidden=true;input.blur();root.querySelector('.cafe-chat-open').hidden=false}root.querySelector('.cafe-chat-fold').onclick=fold;root.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();fold();root.querySelector('.cafe-chat-open').focus()}});
 form.onsubmit=async e=>{e.preventDefault();const text=input.value.trim();if(!seated||busy||!text)return;if(!pending||pending.message!==text)pending={message:text,command:newId()};const token=generation;busy=true;send.disabled=true;input.disabled=true;error.textContent='主理熊正在想…';try{const r=await cloud.cafeChat(pending);if(token!==generation)return;line(text,'visitor');line(r.reply,'host');if(r.ordered)onOrder();input.value='';pending=null;error.textContent=''}catch(e){if(token===generation)error.textContent=e.message||'没有发送成功，请再试一次'}finally{if(token===generation){busy=false;send.disabled=false;input.disabled=false}}};
 return {open(){if(seated)root.querySelector('.cafe-chat-open').click()},seat(value){seated=value;root.hidden=!value;if(!value){panel.hidden=true;root.querySelector('.cafe-chat-open').hidden=false}},reset(){generation++;seated=false;root.hidden=true;panel.hidden=true;root.querySelector('.cafe-chat-open').hidden=false;busy=false;send.disabled=false;input.disabled=false;input.value='';error.textContent='';log.replaceChildren();pending=null}};
}
